CREATE OR REPLACE FUNCTION public.chat_send(p_conversation uuid, p_content text, p_type text DEFAULT 'text'::text, p_file_path text DEFAULT NULL::text, p_reply_to uuid DEFAULT NULL::uuid)
 RETURNS messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me uuid := public.chat_me(); m public.messages;
begin
  if me is null or not public.chat_is_member(p_conversation) then raise exception 'You are not in this conversation'; end if;
  if length(btrim(coalesce(p_content, ''))) = 0 and p_file_path is null then raise exception 'Write a message first'; end if;
  if p_reply_to is not null and not exists (select 1 from public.messages where id = p_reply_to and conversation_id = p_conversation) then
    raise exception 'You can only reply to a message in this conversation';
  end if;
  insert into public.messages(conversation_id, sender_id, content, type, file_path, status, reply_to)
  values (p_conversation, me, left(coalesce(p_content, ''), 10000), coalesce(p_type, 'text'), p_file_path, 'sent', p_reply_to)
  returning * into m;
  update public.conversations set last_message_at = m.created_at, updated_at = now(),
    last_message_preview = case when m.type = 'text' then left(m.content, 120) when m.type = 'image' then 'Photo' when m.type = 'call_log' then m.content else 'Attachment: ' || left(m.content, 100) end
   where id = p_conversation;
  update public.conversation_members set last_read_at = m.created_at
   where conversation_id = p_conversation and user_id = any (public.chat_ids_of(auth.uid()));
  return m;
end $function$

CREATE OR REPLACE FUNCTION public.desk_save_journal(p_date date, p_note text, p_mood text, p_version integer)
 RETURNS desk_journal_entries
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare result public.desk_journal_entries;
begin
  if (select auth.uid()) is null then raise exception 'Sign in to save your desk' using errcode = '28000'; end if;
  if p_version is null then
    insert into public.desk_journal_entries (user_id, entry_date, note, mood)
    values ((select auth.uid()), p_date, p_note, p_mood)
    on conflict (user_id, entry_date) do nothing returning * into result;
  else
    update public.desk_journal_entries set note = p_note, mood = p_mood, version = version + 1, updated_at = now()
    where user_id = (select auth.uid()) and entry_date = p_date and version = p_version
    returning * into result;
  end if;
  if result.user_id is null then raise exception 'This entry changed on another device. Reload before saving.' using errcode = '40001'; end if;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.desk_save_preferences(p_cover text, p_version integer)
 RETURNS desk_preferences
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare result public.desk_preferences;
begin
  if (select auth.uid()) is null then raise exception 'Sign in to save your desk' using errcode = '28000'; end if;
  if p_version is null then
    insert into public.desk_preferences (user_id, cover) values ((select auth.uid()), p_cover)
    on conflict (user_id) do nothing returning * into result;
  else
    update public.desk_preferences set cover = p_cover, version = version + 1, updated_at = now()
    where user_id = (select auth.uid()) and version = p_version returning * into result;
  end if;
  if result.user_id is null then raise exception 'Your preferences changed on another device. Reload before saving.' using errcode = '40001'; end if;
  return result;
end $function$
